import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);String line;while ((line = br.readLine()) != null) {StringTokenizer st = new StringTokenizer(line);while (st.hasMoreTokens()) {int n = Integer.parseInt(st.nextToken());if (n == 42) {out.flush();out.close();return;}out.println(n);}}out.flush();out.close();}}